{"action": "replace_code", "code": "def solve(data):
    left, right = data['day']
    min_len = data['min_length']
    busy = data['busy']

    # Отфильтруем и отсечем интервалы за пределами дня
    valid_intervals = []
    for start, end in busy:
        s, e = max(start, left), min(end, right)
        if s < e:
            valid_intervals.append((s, e))

    if not valid_intervals:
        return [[left, right]] if (right - left) > min_len else []

    # Сортируем по началу, затем по концу
    valid_intervals.sort()

    # Объединяем перескакивающие интервалы
    merged = []
    if valid_intervals:
        curr_start, curr_end = valid_intervals[0]
        for next_start, next_end in valid_intervals[1:]:
            if next_start <= curr_end:
                curr_end = max(curr_end, next_end)
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged.append((curr_start, curr_end))

    # Находим свободные промежутки
    result = []
    current_free_start = left
    for merged_start, merged_end in merged:
        if merged_start > current_free_start:
            free_len = merged_start - current_free_start
            if free_len > min_len:
                result.append([current_free_start, merged_start])
        current_free_start = max(current_free_start, merged_end)

    # Проверка последнего свободного интервала
    if current_free_start < right:
        free_len = right - current_free_start
        if free_len > min_len:
            result.append([current_free_start, right])

    return result
